# --------------------------------------------------------------------------
# API helpers
# --------------------------------------------------------------------------
def api_health(base_url: str, timeout=5):
    try:
        r = requests.get(base_url.rstrip("/") + "/", timeout=timeout)
        if r.status_code == 200:
            return True, r.json().get("message", "Connected")
        return False, f"HTTP {r.status_code}"
    except requests.exceptions.RequestException as e:
        return False, str(e)


def call_classify(base_url: str, api_key: str, file_bytes: bytes, filename: str, mime: str, timeout=20):
    url = base_url.rstrip("/") + "/classify"
    headers = {"X-API-KEY": api_key}
    files = {"file": (filename, file_bytes, mime or "application/octet-stream")}
    try:
        r = requests.post(url, headers=headers, files=files, timeout=timeout)
        if r.status_code == 200:
            return True, r.json()
        try:
            detail = r.json().get("detail", r.text)
        except Exception:
            detail = r.text
        return False, f"HTTP {r.status_code}: {detail}"
    except requests.exceptions.RequestException as e:
        return False, str(e)


def get_logs(base_url: str, api_key: str, timeout=10):
    url = base_url.rstrip("/") + "/logs"
    headers = {"X-API-KEY": api_key}
    try:
        r = requests.get(url, headers=headers, timeout=timeout)
        if r.status_code == 200:
            return True, r.json()
        try:
            detail = r.json().get("detail", r.text)
        except Exception:
            detail = r.text
        return False, f"HTTP {r.status_code}: {detail}"
    except requests.exceptions.RequestException as e:
        return False, str(e)


def check_api_key(base_url: str, api_key: str, timeout=6):
    """
    Validates the API key itself (not just server reachability) by calling a
    protected endpoint (/logs). 403 -> wrong key. 200/503 -> key accepted
    (503 just means Supabase logging isn't configured server-side, the key
    was still correct). Anything else -> unknown / connection error.
    """
    url = base_url.rstrip("/") + "/logs"
    headers = {"X-API-KEY": api_key}
    try:
        r = requests.get(url, headers=headers, timeout=timeout)
        if r.status_code == 403:
            return False, "Invalid API key"
        if r.status_code == 200:
            return True, "Connected"
        if r.status_code == 503:
            return True, "Connected"
        return False, f"HTTP {r.status_code}"
    except requests.exceptions.RequestException as e:
        return False, str(e)


def confidence_band(conf_pct: float):
    if conf_pct >= 90:
        return "high", "badge-high", SUCCESS
    if conf_pct >= 70:
        return "medium", "badge-med", WARN
    return "low", "badge-low", DANGER


def stat_meter(value_pct, label, col=None, decimals=1):
    """
    Big, unmistakably clear number + a slim gradient progress bar underneath.
    Replaces the dial/gauge: same information, easier to read at a glance,
    and reads as a clean modern stat card rather than a speedometer.
    """
    _, _, color = confidence_band(value_pct)
    html = (
        f'<div class="stat-meter">'
        f'<div class="stat-meter-label">{label}</div>'
        f'<div class="stat-meter-value">{value_pct:.{decimals}f}<span class="unit">%</span></div>'
        f'<div class="stat-meter-track">'
        f'<div class="stat-meter-fill" style="width:{min(value_pct,100):.1f}%;'
        f'background:linear-gradient(90deg,{ACCENT},{color});"></div>'
        f'</div></div>'
    )
    target = col if col is not None else st
    target.markdown(html, unsafe_allow_html=True)


def status_pill(ok: bool, text: str, col=None):
    """
    A small colored-dot status badge (connected / error) — replaces plain
    🔴 / 🟢 emoji circles with a themed pill that matches the rest of the UI.
    """
    cls = "ok" if ok else "err"
    html = f'<div class="status-pill {cls}"><span class="status-dot {cls}"></span><span>{text}</span></div>'
    target = col if col is not None else st
    target.markdown(html, unsafe_allow_html=True)


def kpi_card(icon, label, value, accent, col):
    html = (
        f'<div class="kpi-card">'
        f'<div class="kpi-accent-bar" style="background:{accent};"></div>'
        f'<div class="kpi-icon">{icon}</div>'
        f'<div class="kpi-label">{label}</div>'
        f'<div class="kpi-value">{value}</div>'
        f'</div>'
    )
    col.markdown(html, unsafe_allow_html=True)


def loom_logo(sub_label="Fashion-MNIST Classification", size=46, clickable=True):
    inner = (
        f'<div class="loom-logo-row">'
        f'<div class="loom-mark" style="width:{size}px;height:{size}px;">'
        f'<img class="loom-mark-img" src="data:image/png;base64,{LOOM_LOGO_B64}" />'
        f'</div>'
        f'<div><div class="loom-wordmark">LOOM</div>'
        f'<div class="loom-wordmark-sub">{sub_label}</div></div>'
        f'</div>'
    )
    if clickable:
        inner = f'<a href="?nav=home" target="_self" class="loom-logo-link">{inner}</a>'
    st.markdown(inner, unsafe_allow_html=True)


def fingerprint(*parts) -> str:
    h = hashlib.sha256()
    for p in parts:
        h.update(str(p).encode("utf-8"))
    return h.hexdigest()


def class_grid(counts=None):
    """Renders the 10 Fashion-MNIST classes as chips, optionally with a count under each."""
    cols = st.columns(5, gap="medium")
    for i, name in enumerate(CLASS_NAMES):
        with cols[i % 5]:
            count_html = ""
            if counts is not None:
                count_html = f'<div class="idx">{counts.get(name, 0):,}</div>'
            html = (
                f'<div class="class-chip">'
                f'<div class="icon">{CLASS_ICONS[name]}</div>'
                f'<div class="name">{name}</div>'
                f'<div class="idx">idx {i}</div>'
                f'{count_html}'
                f'</div>'
            )
            st.markdown(html, unsafe_allow_html=True)
        if i % 5 == 4 and i != len(CLASS_NAMES) - 1:
            cols = st.columns(5, gap="medium")


